import 'package:flutter/material.dart';
import '../../core/app_controller.dart';
import '../../core/widgets/app_header.dart';

class ModulesScreen extends StatelessWidget {const ModulesScreen({super.key});
@override Widget build(BuildContext context){final app=AppScope.of(context);final cards=<Widget>[_ModuleCard(title:'Monitoreo',subtitle:'Plagas y enfermedades',asset:'assets/images/plagas.webp',onTap:()=>app.go(AppPage.monitoringList)),if(app.user?.canSeeAspersion==true)_ModuleCard(title:'Aspersión',subtitle:'Sesiones, eficiencia y mapas',asset:'assets/images/aspersion.webp',onTap:()=>app.go(AppPage.aspersionList)),_ModuleCard(title:'NDVI',subtitle:'Índices de vegetación y contornos',asset:'assets/images/ndbi.webp',onTap:()=>app.go(AppPage.ndviList))];return Scaffold(body:Column(children:[const AppHeader(title:'Módulos de trabajo'),Expanded(child:ListView(padding:const EdgeInsets.all(18),children:[Text('Módulos de trabajo',textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('Elige una opción para continuar',textAlign:TextAlign.center),const SizedBox(height:20),...cards]) )]));}}
class _ModuleCard extends StatelessWidget{const _ModuleCard({required this.title,required this.subtitle,required this.asset,required this.onTap});final String title,subtitle,asset;final VoidCallback onTap;@override Widget build(BuildContext context)=>Card(clipBehavior:Clip.antiAlias,margin:const EdgeInsets.only(bottom:16),child:InkWell(onTap:onTap,child:Row(children:[SizedBox(width:115,height:110,child:Image.asset(asset,fit:BoxFit.cover)),Expanded(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:5),Text(subtitle,style:const TextStyle(color:Colors.black54))]))),const Padding(padding:EdgeInsets.all(12),child:Icon(Icons.chevron_right))])));}
